// Idempotency guard
if (document.getElementById('qs-toolbar')) return;

/* ── Inject styles ── */
const style = document.createElement('style');
style.id = 'qs-toolbar-styles';
style.textContent = `
  #qs-toolbar {
    position: sticky;
    top: 0;
    z-index: 10000;
    display: flex;
    align-items: center;
    gap: 0;
    padding: 0 18px;
    height: 44px;
    background: linear-gradient(90deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    box-shadow: 0 2px 12px rgba(0,0,0,0.45);
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    font-size: 12px;
    color: #e0e0e0;
    user-select: none;
    flex-wrap: nowrap;
    overflow: hidden;
  }
  #qs-toolbar .qs-brand {
    display: flex;
    align-items: center;
    gap: 6px;
    font-weight: 700;
    font-size: 11px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #a8d8ff;
    margin-right: 18px;
    white-space: nowrap;
    flex-shrink: 0;
  }
  #qs-toolbar .qs-brand svg {
    width: 16px; height: 16px; flex-shrink: 0;
  }
  #qs-toolbar .qs-divider {
    width: 1px;
    height: 26px;
    background: rgba(255,255,255,0.15);
    margin: 0 16px;
    flex-shrink: 0;
  }
  #qs-toolbar .qs-control {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;
  }
  #qs-toolbar .qs-label {
    white-space: nowrap;
    color: #b0c4de;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.04em;
    display: flex;
    align-items: center;
    gap: 5px;
  }
  #qs-toolbar .qs-label svg {
    width: 13px; height: 13px; opacity: 0.8;
  }
  #qs-toolbar .qs-value {
    color: #a8d8ff;
    font-weight: 700;
    font-size: 11px;
    min-width: 30px;
    text-align: right;
  }
  /* Slider */
  #qs-toolbar input[type=range] {
    -webkit-appearance: none;
    appearance: none;
    width: 90px;
    height: 4px;
    border-radius: 2px;
    background: rgba(255,255,255,0.18);
    outline: none;
    cursor: pointer;
    transition: background 0.2s;
  }
  #qs-toolbar input[type=range]::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 14px; height: 14px;
    border-radius: 50%;
    background: #a8d8ff;
    box-shadow: 0 0 0 3px rgba(168,216,255,0.25);
    cursor: pointer;
    transition: box-shadow 0.15s, background 0.15s;
  }
  #qs-toolbar input[type=range]:hover::-webkit-slider-thumb {
    background: #ffffff;
    box-shadow: 0 0 0 4px rgba(168,216,255,0.4);
  }
  #qs-toolbar input[type=range]::-moz-range-thumb {
    width: 14px; height: 14px;
    border-radius: 50%;
    background: #a8d8ff;
    border: none;
    cursor: pointer;
  }
  /* Dark mode toggle */
  #qs-toolbar .qs-toggle-wrap {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;
  }
  #qs-toolbar .qs-toggle {
    position: relative;
    width: 40px;
    height: 22px;
    flex-shrink: 0;
  }
  #qs-toolbar .qs-toggle input { opacity: 0; width: 0; height: 0; position: absolute; }
  #qs-toolbar .qs-toggle-track {
    position: absolute;
    inset: 0;
    border-radius: 11px;
    background: rgba(255,255,255,0.15);
    cursor: pointer;
    transition: background 0.25s;
    border: 1px solid rgba(255,255,255,0.2);
  }
  #qs-toolbar .qs-toggle input:checked + .qs-toggle-track {
    background: #3a7bd5;
    border-color: #3a7bd5;
  }
  #qs-toolbar .qs-toggle-thumb {
    position: absolute;
    top: 3px; left: 3px;
    width: 16px; height: 16px;
    border-radius: 50%;
    background: #ffffff;
    box-shadow: 0 1px 4px rgba(0,0,0,0.4);
    transition: left 0.25s cubic-bezier(.4,0,.2,1);
    pointer-events: none;
  }
  #qs-toolbar .qs-toggle input:checked ~ .qs-toggle-thumb {
    left: 21px;
  }
  /* Dark mode body class effect */
  body.qs-dark-mode {
    filter: invert(1) hue-rotate(180deg);
  }
  body.qs-dark-mode img,
  body.qs-dark-mode video,
  body.qs-dark-mode [class*="fandom-ad"],
  body.qs-dark-mode iframe,
  body.qs-dark-mode svg {
    filter: invert(1) hue-rotate(180deg);
  }
  body.qs-dark-mode #qs-toolbar {
    filter: none;
  }
  /* Spacer pushes dark mode to far right */
  #qs-toolbar .qs-spacer { flex: 1 1 auto; min-width: 8px; }
  /* Reset button */
  #qs-toolbar .qs-reset {
    display: flex; align-items: center; gap: 4px;
    background: rgba(255,255,255,0.08);
    border: 1px solid rgba(255,255,255,0.18);
    border-radius: 5px;
    color: #b0c4de;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.04em;
    padding: 3px 9px;
    cursor: pointer;
    transition: background 0.15s, color 0.15s;
    white-space: nowrap;
    flex-shrink: 0;
  }
  #qs-toolbar .qs-reset:hover {
    background: rgba(255,255,255,0.18);
    color: #fff;
  }
`;
document.head.appendChild(style);

/* ── Build toolbar HTML ── */
const bar = document.createElement('div');
bar.id = 'qs-toolbar';
bar.setAttribute('role', 'toolbar');
bar.setAttribute('aria-label', 'Quick Settings');
bar.innerHTML = `
  <div class="qs-brand">
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <circle cx="12" cy="12" r="3"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14M4.93 4.93a10 10 0 0 0 0 14.14"/>
    </svg>
    Quick Settings
  </div>

  <div class="qs-divider"></div>

  <!-- Font Size -->
  <div class="qs-control" id="qs-fontsize-ctrl">
    <span class="qs-label">
      <svg viewBox="0 0 24 24" fill="currentColor">
        <text x="2" y="18" font-size="12" font-family="sans-serif" font-weight="bold">A</text>
        <text x="13" y="20" font-size="16" font-family="sans-serif" font-weight="bold">A</text>
      </svg>
      Font Size
    </span>
    <input type="range" id="qs-font-slider" min="80" max="140" step="5" value="100" aria-label="Font size">
    <span class="qs-value" id="qs-font-val">100%</span>
  </div>

  <div class="qs-divider"></div>

  <!-- Layout Width -->
  <div class="qs-control" id="qs-width-ctrl">
    <span class="qs-label">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <path d="M21 3H3M21 21H3M17 12H7M21 8H3M21 16H3"/>
      </svg>
      Layout Width
    </span>
    <input type="range" id="qs-width-slider" min="60" max="100" step="5" value="100" aria-label="Layout width">
    <span class="qs-value" id="qs-width-val">100%</span>
  </div>

  <div class="qs-spacer"></div>

  <!-- Dark Mode Toggle -->
  <div class="qs-toggle-wrap">
    <span class="qs-label">
      <svg viewBox="0 0 24 24" fill="currentColor">
        <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/>
      </svg>
      Dark Mode
    </span>
    <label class="qs-toggle" aria-label="Toggle dark mode">
      <input type="checkbox" id="qs-dark-toggle">
      <span class="qs-toggle-track"></span>
      <span class="qs-toggle-thumb"></span>
    </label>
  </div>

  <div class="qs-divider"></div>

  <button class="qs-reset" id="qs-reset-btn" title="Reset all settings to default">
    <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
      <polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 .49-4.36"/>
    </svg>
    Reset
  </button>
`;

/* ── Insert at very top of body ── */
document.body.insertBefore(bar, document.body.firstChild);

/* ── Restore saved state ── */
const saved = {
  font:  parseInt(localStorage.getItem('qs_font')  || '100', 10),
  width: parseInt(localStorage.getItem('qs_width') || '100', 10),
  dark:  localStorage.getItem('qs_dark') === '1'
};

/* ── Targets for font / width ── */
const CONTENT_SELECTORS = '.page__main, .page-content, .mw-parser-output, .page-header';
const LAYOUT_SELECTOR   = '.resizable-container, .page.has-right-rail, .main-container';

function applyFont(val) {
  document.querySelectorAll(CONTENT_SELECTORS).forEach(el => {
    el.style.fontSize = val + '%';
  });
  document.getElementById('qs-font-val').textContent = val + '%';
  document.getElementById('qs-font-slider').value = val;
  localStorage.setItem('qs_font', val);
}

function applyWidth(val) {
  document.querySelectorAll(LAYOUT_SELECTOR).forEach(el => {
    el.style.maxWidth = val + '%';
    el.style.marginLeft = 'auto';
    el.style.marginRight = 'auto';
  });
  document.getElementById('qs-width-val').textContent = val + '%';
  document.getElementById('qs-width-slider').value = val;
  localStorage.setItem('qs_width', val);
}

function applyDark(on) {
  if (on) {
    document.body.classList.add('qs-dark-mode');
  } else {
    document.body.classList.remove('qs-dark-mode');
  }
  document.getElementById('qs-dark-toggle').checked = on;
  localStorage.setItem('qs_dark', on ? '1' : '0');
}

/* Apply saved state */
applyFont(saved.font);
applyWidth(saved.width);
applyDark(saved.dark);

/* ── Wire events ── */
document.getElementById('qs-font-slider').addEventListener('input', function() {
  applyFont(parseInt(this.value, 10));
});
document.getElementById('qs-width-slider').addEventListener('input', function() {
  applyWidth(parseInt(this.value, 10));
});
document.getElementById('qs-dark-toggle').addEventListener('change', function() {
  applyDark(this.checked);
});
document.getElementById('qs-reset-btn').addEventListener('click', function() {
  applyFont(100);
  applyWidth(100);
  applyDark(false);
});
